SELECT DISTINCT m.user_name AS userName, m.emp_name AS empName, m.emp_no AS empNo FROM ( SELECT (SELECT m2.depart_code FROM safety_group_info gi2 INNER JOIN ytsafety_sys_responsible_mapping m2 ON FIND_IN_SET(m2.depart_code, gi2.org_code_path) > 0 AND m2.role_code = #{roleCode} WHERE gi2.code = gi.code AND gi2.status = 'Y' ORDER BY FIND_IN_SET(m2.depart_code, gi2.org_code_path) DESC LIMIT 1) AS depart_code FROM safety_group_info gi WHERE gi.code IN
#{orgCode}
AND gi.status = 'Y' ) od INNER JOIN ytsafety_sys_responsible_mapping m ON m.depart_code = od.depart_code AND m.role_code = #{roleCode}

SELECT DISTINCT m.user_name AS userName, m.emp_name AS empName, m.emp_no AS empNo FROM ( SELECT (SELECT m2.depart_code FROM safety_group_info gi2 INNER JOIN ytsafety_sys_responsible_mapping m2 ON FIND_IN_SET(m2.depart_code, gi2.org_code_path) > 0 AND m2.role_code = #{roleCode} AND m2.factory_id = #{factoryId} WHERE gi2.code = gi.code AND gi2.status = 'Y' ORDER BY FIND_IN_SET(m2.depart_code, gi2.org_code_path) DESC LIMIT 1) AS depart_code FROM safety_group_info gi WHERE gi.code IN
#{orgCode}
AND gi.status = 'Y' ) od INNER JOIN ytsafety_sys_responsible_mapping m ON m.depart_code = od.depart_code AND m.role_code = #{roleCode} AND m.factory_id = #{factoryId}
